rule.example:
// 1. Single-line title (no wrapping)
text #title {
    at: (40px, 40px);
    content: "Overview Dashboard";
    font-size: 32px;
    font-weight: 700;
    color: #ffffff;
}

// 2. Multi-line body paragraph (wraps at 500px, hugs wrapped height)
text #body {
    at: below #title offset 12px;
    content: "The declarative compiler converts structured AST nodes into production raster images.";
    font-size: 15px;
    line-height: 1.6;
    color: #9EB0A3;
    size: 500px hug;
}

// Pixel-perfect tab pill (24px height container)
group #tabActive {
    size: 96px 24px;
    rect #tabBg { size: 96px 24px; radius: 4px; fill: alpha(#00f0ff, 0.12); at: (0px, 0px); }
    // Text y = 10px instead of theoretical 7px to compensate for top-baseline ascent:
    text #tabLabel { content: "banner.toad"; font-size: 11px; font-weight: 700; color: #00f0ff; at: (12px, 10px); }
}
